import test from 'node:test';
import assert from 'node:assert/strict';
import {inspectScript} from '../../scripts/verify-package.mjs';

// The exact lexical prototype-repair shape generated by React 19 is inert:
// no reading the constructor, no call, no Function/eval, no privilege change.
const prototypeRepair='var shell=(function(){function Parent(){}function Component(){}'+
  'var local=Component.prototype=new Parent;local.constructor=Component;return Component})()';

test('fixed React shell accepts only local component prototype restoration',()=>{
  assert.deepEqual(inspectScript(prototypeRepair,'ui/tool-shell.js'),
    {approvedAsyncBodyConstructors:0});
});

test('other entries cannot inherit the fixed React prototype exception',()=>{
  assert.throws(()=>inspectScript(prototypeRepair,'agents/health.js'),
    /Unapproved dynamic constructor reference/);
});

test('React shell still forbids constructor reads, mismatched writes and dynamic calls',()=>{
  const head='var shell=(function(){function Parent(){}function Component(){}'+
    'var local=Component.prototype=new Parent;';
  for(const tail of [
    'return local.constructor})()',
    'local.constructor=Parent;return Component})()',
    'var ctor=local.constructor;return ctor})()',
    'return local["constructor"]})()',
    'return Function("return 1")()})()'
  ]){
    assert.throws(()=>inspectScript(head+tail,'ui/tool-shell.js'),
      /Unapproved dynamic constructor reference|Dynamic execution/);
  }
});
